use super::*;
use photocraft_engine::doc::{Affine, AlphaChannel, BlendMode, Document, Layer, LayerMask, Metadata, PixelFormat, Rect, SampleType, Slice, SliceOrigin, SmartFilter};
use photocraft_raster::Surface;
use std::{io::Read, path::PathBuf, sync::{Weak,atomic::{AtomicBool,Ordering}}};

struct Directory(PathBuf);
impl Drop for Directory{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
fn directory()->Directory{let path=std::env::temp_dir().join(format!("linked-transform-{}",ulid::Ulid::new()));std::fs::create_dir_all(&path).unwrap();Directory(path)}
fn rgba()->Vec<u8>{vec![255,0,0,255,0,255,0,255,0,0,255,255,255,255,255,255]}
fn encoded(format:&str,pixels:Vec<u8>)->Vec<u8>{match format{"png"=>{let image=photocraft_codecs::Image::from_u8(2,2,photocraft_codecs::ChannelLayout::Rgba,pixels).unwrap();photocraft_codecs::encode(&image,photocraft_codecs::Format::Png,&Default::default()).unwrap()},"psd"|"psb"=>{use photocraft_psd::{Compression,LayerSpec,PixelData,PsdBuilder,Version};let mut builder=PsdBuilder::new(2,2).version(if format=="psb"{Version::Psb}else{Version::Psd}).compression(Compression::Raw);builder.push_layer(LayerSpec::new("Known",0,0,2,2,PixelData::Rgba8(pixels.clone())));builder.composite(PixelData::Rgba8(pixels));builder.to_bytes().unwrap()},"pcraft"=>photocraft_engine::smart_cmds::encode_source(&photocraft_io::import("source.png",&encoded("png",pixels)).unwrap().document).unwrap(),_=>unreachable!()}}
fn object_layer(name:&str,source:SmartSource,x:i32,y:i32,format:PixelFormat)->Layer{let mut cache=Surface::new(format);cache.fill_rect(Rect::from_xywh(x,y,1,1),&[0.25,0.5,0.75,1.]);let mut object=SmartObject::new(source,Affine::translate(f64::from(x),f64::from(y)),Some(cache));object.smart_filters=vec![SmartFilter{command:"filter.cameraRaw".into(),params:json!({"exposure":0,"vendor":{"keep":[null,7]}}),visible:true,opacity:1.,blend:BlendMode::Normal},SmartFilter{command:"filter.other.offset".into(),params:json!({"horizontal":1,"vertical":0,"undefinedAreas":"transparent"}),visible:true,opacity:1.,blend:BlendMode::Normal},SmartFilter{command:"filter.other.offset".into(),params:json!({"horizontal":90}),visible:false,opacity:0.42,blend:BlendMode::Multiply}];let mut filter_mask=LayerMask::hide_all();filter_mask.surface.fill_rect(Rect::from_xywh(x,y,1,1),&[0.4]);filter_mask.enabled=false;filter_mask.linked=false;filter_mask.density=0.42;filter_mask.feather=1.25;object.filter_mask=Some(filter_mask);object.psd_raw=Some(Arc::new(b"retained placed data".to_vec()));let mut layer=Layer::new(name,LayerContent::Smart(object));let mut mask=LayerMask::hide_all();mask.surface.fill_rect(Rect::from_xywh(x,y,1,1),&[0.7]);mask.linked=false;mask.density=0.6;layer.mask=Some(mask);for key in [*b"SoLd",*b"SoLE",*b"PlLd",*b"zzzz"]{layer.psd_blocks.push((key,Arc::new([key.as_slice(),b" retained"].concat())));}layer}
struct Fixture{directory:Directory,engine:Session,id:LayerId,other:LayerId,embedded:LayerId,group:LayerId,raster:LayerId,path:PathBuf,bytes:Vec<u8>}
fn fixture(depth:u32,format:&str)->Fixture{let directory=directory();let path=directory.0.join(format!("source.{format}"));let bytes=encoded(format,rgba());std::fs::write(&path,&bytes).unwrap();let mut engine=Session::new();engine.execute("file.new",json!({"width":16,"height":12,"depth":depth})).unwrap();let fmt=engine.active().unwrap().doc.pixel_format();let first=object_layer("Original linked",SmartSource::Linked{path:path.to_string_lossy().into()},2,1,fmt);let mut other=object_layer("Repeated linked",SmartSource::Linked{path:path.to_string_lossy().into()},8,1,fmt);other.visible=false;let embedded=object_layer("Embedded sibling",SmartSource::Embedded{file_name:format!("embedded.{format}"),bytes:Arc::new(bytes.clone())},2,6,fmt);let raster=Layer::raster("Raster sibling",fmt);let ids=[first.id,other.id,embedded.id,raster.id];let group=Layer::group("Nested group",vec![other,Layer::group("Inner group",vec![embedded,raster])]);let group_id=group.id;engine.edit("Transform fixture",|doc,current|{doc.layers=vec![first,group];*current=Some(ids[0]);let mut selection=Surface::new(PixelFormat::GRAY8);selection.fill_rect(Rect::from_xywh(2,1,1,1),&[0.5]);doc.selection=Some(selection.clone());doc.channels.push(AlphaChannel::new("Retained alpha",selection.clone()));doc.quick_mask=Some(AlphaChannel::new("Quick Mask",selection));doc.metadata.psd_global_blocks.push((*b"8BIM",*b"zzzz",Arc::new(b"retained globals".to_vec())));doc.slices.list=vec![Slice{id:1,origin:SliceOrigin::Layer,layer:Some(ids[0]),rect:Rect::from_xywh(2,1,1,1),..Default::default()}];Ok(())}).unwrap();let index=engine.active_index().unwrap();engine.execute("document.activate",json!({"document":index})).unwrap();let state=engine.active_mut().unwrap();state.selected_layers=vec![ids[0],ids[1]];state.layer_anchor=Some(ids[1]);state.channel_view.target=photocraft_engine::channel_cmds::ChannelTarget::Alpha(0);engine.tools.foreground=[0.2,0.3,0.4,0.5];engine.tools.background=[0.7,0.6,0.5,0.4];let state=engine.active().unwrap();engine.edit_state.fade=Some(photocraft_engine::edit_menu_cmds::FadeSource{doc:state.doc.id,revision:state.revision,layer:ids[0],mask:false,label:"Older transform Fade".into()});Fixture{directory,engine,id:ids[0],other:ids[1],embedded:ids[2],group:group_id,raster:ids[3],path,bytes}}
fn smart(doc:&Document,id:LayerId)->&SmartObject{let LayerContent::Smart(object)=&doc.layer(id).unwrap().content else{panic!("Not a Smart Object")};object}
fn twin(engine:&Session)->Session{let state=engine.active().unwrap();let mut copy=Session::new();copy.add_document(Document::new("Twin",state.doc.size,state.doc.mode,state.doc.depth),None);*copy.active_mut().unwrap()=state.clone();copy.journal=engine.journal.clone();copy.tools=engine.tools.clone();copy.presets=engine.presets.clone();copy.patterns=engine.patterns.clone();copy.clipboard=engine.clipboard.clone();copy.style_clipboard=engine.style_clipboard.clone();copy.edit_state=engine.edit_state.clone();super::super::super::color_views::Snapshot::capture(engine).unwrap().install(&mut copy).unwrap();copy}
fn same(actual:&Session,native:&Session){let a=actual.active().unwrap();let n=native.active().unwrap();assert_eq!(a.doc,n.doc);assert_eq!(a.history.entries(),n.history.entries());assert_eq!(a.history.past_len(),n.history.past_len());for index in 0..a.history.past_len(){assert_eq!(a.history.state(index),n.history.state(index));}assert_eq!(a.history.redo_labels().collect::<Vec<_>>(),n.history.redo_labels().collect::<Vec<_>>());assert_eq!((a.revision,a.saved_revision,&a.coalesce,a.active_layer,&a.selected_layers,a.layer_anchor,&a.path,&a.last_damage),(n.revision,n.saved_revision,&n.coalesce,n.active_layer,&n.selected_layers,n.layer_anchor,&n.path,&n.last_damage));assert_eq!(a.channel_view,n.channel_view);assert_eq!(a.isolated_layers,n.isolated_layers);assert_eq!(a.fx_collapsed,n.fx_collapsed);assert_eq!(format!("{:?}",a.symmetry_path),format!("{:?}",n.symmetry_path));assert_eq!(actual.journal,native.journal);assert_eq!(actual.edit_state.fade,native.edit_state.fade);assert_eq!(actual.tools.foreground,native.tools.foreground);assert_eq!(actual.tools.background,native.tools.background);assert_eq!(actual.tools.brush,native.tools.brush);assert_eq!(actual.style_clipboard,native.style_clipboard);assert_eq!(format!("{:?}",actual.clipboard),format!("{:?}",native.clipboard));assert_eq!(super::super::super::tools::presets(actual),super::super::super::tools::presets(native));assert_eq!(super::super::super::color_views::key(actual).unwrap(),super::super::super::color_views::key(native).unwrap());}
fn unchanged(engine:&Session,before:&Session){same(engine,before);assert!(Arc::ptr_eq(&engine.active().unwrap().doc,&before.active().unwrap().doc));}
fn host(engine:&mut Session,params:Value)->Result<Value,String>{super::super::super::execute_view_command(engine,COMMAND,params)}
fn translated()->Value{json!({"matrix":[1,0,0,1,3,2]})}
fn checked(_:LayerId,meta:&Metadata,object:&SmartObject)->Result<Option<super::super::Bytes>,String>{super::super::super::smart::source_bytes_checked(meta,&object.source,||Ok(()))}
fn pixels(engine:&Session,id:LayerId,rect:Rect,raw:&[u8]){let doc=&engine.active().unwrap().doc;let cache=smart(doc,id).cache.as_ref().unwrap();let tolerance=match doc.depth{SampleType::U8=>1./255.,SampleType::U16=>2./65535.,SampleType::F32=>1e-6};for y in -2..16{for x in -2..20{let expected=if rect.contains(x,y){let at=((y-rect.y0)*rect.width()as i32+x-rect.x0)as usize*4;[raw[at]as f32/255.,raw[at+1]as f32/255.,raw[at+2]as f32/255.,raw[at+3]as f32/255.]}else{[0.;4]};let actual=cache.pixel(x,y);for channel in 0..4{assert!((actual[channel]-expected[channel]).abs()<=tolerance,"{:?}/{x},{y}/{channel}:{} != {}",doc.depth,actual[channel],expected[channel]);}assert_eq!(actual[3],expected[3]);}}}
fn fallback_pixel(engine:&Session,id:LayerId,x0:i32,y0:i32){let doc=&engine.active().unwrap().doc;let cache=smart(doc,id).cache.as_ref().unwrap();let tolerance=match doc.depth{SampleType::U8=>1./255.,SampleType::U16=>2./65535.,SampleType::F32=>1e-6};for y in 0..12{for x in 0..16{let expected=if(x,y)==(x0,y0){[0.25,0.5,0.75,1.]}else{[0.;4]};let actual=cache.pixel(x,y);for channel in 0..4{assert!((actual[channel]-expected[channel]).abs()<=tolerance);}assert_eq!(actual[3],expected[3]);}}}
fn same_source_and_fields(engine:&Session,before:&Document,id:LayerId){let doc=&engine.active().unwrap().doc;let after=smart(doc,id);let original=smart(before,id);assert_eq!(after.source,original.source);assert_eq!(after.psd_raw,original.psd_raw);assert_eq!(after.smart_filters,original.smart_filters);assert_eq!(doc.layer(id).unwrap().psd_blocks,before.layer(id).unwrap().psd_blocks);assert_eq!(doc.metadata,before.metadata);}

#[test]
fn linked_transform_affine_four_formats_three_depths_match_native_and_independent_non_neutral_pixels(){
    for depth in [8,16,32]{for format in ["png","psd","psb","pcraft"]{for rotate in [false,true]{let mut f=fixture(depth,format);let before=f.engine.active().unwrap().doc.clone();let past=f.engine.active().unwrap().history.past_len();let journal=f.engine.journal.len();let mut native=twin(&f.engine);let params=if rotate{json!({"matrix":[-1,0,0,-1,8,6]})}else{translated()};assert_eq!(host(&mut f.engine,params.clone()).unwrap(),native.execute(COMMAND,params).unwrap());same(&f.engine,&native);same_source_and_fields(&f.engine,&before,f.id);let doc=&f.engine.active().unwrap().doc;assert_eq!(doc.layer(f.group),before.layer(f.group));assert_eq!(doc.channels,before.channels);assert_eq!(doc.quick_mask,before.quick_mask);assert_eq!(doc.layer(f.id).unwrap().mask,before.layer(f.id).unwrap().mask);if rotate{assert_eq!(smart(doc,f.id).transform,Affine{m:[-1.,0.,0.,-1.,6.,5.]});pixels(&f.engine,f.id,Rect::new(5,3,7,5),&[255,255,255,255,0,0,255,255,0,255,0,255,255,0,0,255]);}else{assert_eq!(smart(doc,f.id).transform,Affine::translate(5.,3.));pixels(&f.engine,f.id,Rect::new(6,3,8,5),&rgba());}assert_eq!(f.engine.active().unwrap().history.past_len(),past+1);assert_eq!(f.engine.journal.len(),journal+1);let after=doc.clone();f.engine.execute("edit.undo",json!({})).unwrap();native.execute("edit.undo",json!({})).unwrap();same(&f.engine,&native);assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before));f.engine.execute("edit.redo",json!({})).unwrap();native.execute("edit.redo",json!({})).unwrap();same(&f.engine,&native);assert_eq!(f.engine.active().unwrap().doc,after);}}}
}

#[test]
fn linked_transform_projective_quad_retains_all_four_corners_and_native_replay_cache(){
    for depth in [8,16,32]{let mut f=fixture(depth,"png");let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let params=json!({"rect":[2,1,4,3],"quad":[[4,2],[8,2],[7,6],[3,5]],"interpolation":"nearest"});assert_eq!(host(&mut f.engine,params.clone()).unwrap(),native.execute(COMMAND,params).unwrap());same(&f.engine,&native);same_source_and_fields(&f.engine,&before,f.id);let object=smart(&f.engine.active().unwrap().doc,f.id);assert!(object.perspective.is_some());let h=photocraft_engine::smart_cmds::placement(object);for (source,expected)in [((0.,0.),(4.,2.)),((2.,0.),(8.,2.)),((2.,2.),(7.,6.)),((0.,2.),(3.,5.))]{let actual=h.apply(source.0,source.1);assert!((actual.0-expected.0).abs()<=1e-9);assert!((actual.1-expected.1).abs()<=1e-9);}let cache=object.cache.clone();let id=f.id;f.engine.edit("Public source replay",|doc,_|{assert!(photocraft_engine::smart_cmds::refresh(doc,id)?);Ok(())}).unwrap();assert_eq!(smart(&f.engine.active().unwrap().doc,f.id).cache,cache);}
}

#[test]
fn linked_transform_missing_and_decode_errors_keep_native_warped_cache_instead_of_refusing(){
    for depth in [8,16,32]{for failure in ["missing","corrupt","wrongBasename"]{let mut f=fixture(depth,"png");match failure{"missing"=>std::fs::remove_file(&f.path).unwrap(),"corrupt"=>std::fs::write(&f.path,b"opaque invalid transform source").unwrap(),_=>{let path=f.directory.0.join("invalid.pcraft");std::fs::write(&path,b"invalid native bundle bytes").unwrap();let id=f.id;f.engine.edit("Decode refusal source",|doc,_|{let LayerContent::Smart(object)=&mut doc.layer_mut(id).unwrap().content else{unreachable!()};object.source=SmartSource::Linked{path:path.to_string_lossy().into()};Ok(())}).unwrap();}}let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let params=translated();assert_eq!(host(&mut f.engine,params.clone()).unwrap(),native.execute(COMMAND,params).unwrap());same(&f.engine,&native);same_source_and_fields(&f.engine,&before,f.id);assert_eq!(smart(&f.engine.active().unwrap().doc,f.id).transform,Affine::translate(5.,3.));fallback_pixel(&f.engine,f.id,5,3);}}
}

#[test]
fn linked_transform_lone_coverage_targets_do_not_read_smart_source_but_linked_mask_moves_whole_smart(){
    for target in [json!("mask"),json!({"channel":0}),json!("quickMask")]{let mut f=fixture(16,"png");std::fs::OpenOptions::new().write(true).open(&f.path).unwrap().set_len(super::super::super::MAX_INPUT_BYTES+1).unwrap();let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let mut params=translated();params["target"]=target;assert_eq!(host(&mut f.engine,params.clone()).unwrap(),native.execute(COMMAND,params).unwrap());same(&f.engine,&native);assert_eq!(smart(&f.engine.active().unwrap().doc,f.id),smart(&before,f.id));fallback_pixel(&f.engine,f.id,2,1);}
    let mut f=fixture(16,"png");let id=f.id;f.engine.edit("Linked mask",|doc,_|{doc.layer_mut(id).unwrap().mask.as_mut().unwrap().linked=true;Ok(())}).unwrap();let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let mut params=translated();params["target"]=json!("mask");host(&mut f.engine,params.clone()).unwrap();native.execute(COMMAND,params).unwrap();same(&f.engine,&native);same_source_and_fields(&f.engine,&before,f.id);pixels(&f.engine,f.id,Rect::new(6,3,8,5),&rgba());assert_ne!(f.engine.active().unwrap().doc.layer(f.id).unwrap().mask,before.layer(f.id).unwrap().mask);
}

#[test]
fn linked_transform_explicit_inactive_target_overrides_selection_while_raster_targets_stay_native(){
    for target in ["inactive","raster"]{let mut f=fixture(16,"png");let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let mut params=translated();params["layer"]=json!(if target=="inactive"{f.other.0}else{f.raster.0});params["rect"]=json!([0,0,1,1]);host(&mut f.engine,params.clone()).unwrap();native.execute(COMMAND,params).unwrap();same(&f.engine,&native);assert_eq!(f.engine.active().unwrap().doc.layer(f.id),before.layer(f.id));if target=="inactive"{pixels(&f.engine,f.other,Rect::new(12,3,14,5),&rgba());}}
}

#[test]
fn linked_transform_group_nested_repeated_paths_and_embedded_siblings_follow_native_order_and_full_state(){
    let mut f=fixture(16,"png");let group=f.group;let id=f.id;f.engine.edit("All Smart occurrences in group",|doc,active|{let first=doc.remove(id).unwrap();doc.layer_mut(group).unwrap().children_mut().unwrap().insert(0,first);*active=Some(group);Ok(())}).unwrap();let index=f.engine.active_index().unwrap();f.engine.execute("document.activate",json!({"document":index})).unwrap();let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let mut params=translated();params["layer"]=json!(group.0);assert_eq!(host(&mut f.engine,params.clone()).unwrap(),native.execute(COMMAND,params).unwrap());same(&f.engine,&native);for id in [f.id,f.other,f.embedded]{same_source_and_fields(&f.engine,&before,id);}pixels(&f.engine,f.id,Rect::new(6,3,8,5),&rgba());pixels(&f.engine,f.other,Rect::new(12,3,14,5),&rgba());pixels(&f.engine,f.embedded,Rect::new(6,8,8,10),&rgba());
}

#[test]
fn linked_transform_one_checked_read_per_occurrence_retires_linked_pins_and_keeps_original_references(){
    let mut f=fixture(16,"png");let group=f.group;let id=f.id;f.engine.edit("Group ordered reads",|doc,active|{let first=doc.remove(id).unwrap();doc.layer_mut(group).unwrap().children_mut().unwrap().insert(0,first);*active=Some(group);Ok(())}).unwrap();let index=f.engine.active_index().unwrap();f.engine.execute("document.activate",json!({"document":index})).unwrap();let before=f.engine.active().unwrap().doc.clone();let mut ids=Vec::new();let mut pins:Vec<Weak<Vec<u8>>>=Vec::new();let red=[255,0,0,255].repeat(4);let blue=[0,0,255,255].repeat(4);let mut params=translated();params["layer"]=json!(group.0);
    run_with(&mut f.engine,&params,|id,meta,object|{assert!(pins.iter().all(|pin|pin.upgrade().is_none()));ids.push(id);assert_eq!(object.source,smart(&before,id).source);if id==f.id{assert_eq!(object.transform,Affine::translate(5.,3.));std::fs::write(&f.path,encoded("png",red.clone())).unwrap();}else if id==f.other{assert_eq!(object.transform,Affine::translate(11.,3.));std::fs::write(&f.path,encoded("png",blue.clone())).unwrap();}let source=checked(id,meta,object)?;if matches!(object.source,SmartSource::Linked{..}){pins.push(Arc::downgrade(&source.as_ref().unwrap().1));}Ok(source)}).unwrap();
    assert_eq!(ids,vec![f.id,f.other,f.embedded]);assert!(pins.iter().all(|pin|pin.upgrade().is_none()));pixels(&f.engine,f.id,Rect::new(6,3,8,5),&red);pixels(&f.engine,f.other,Rect::new(12,3,14,5),&blue);pixels(&f.engine,f.embedded,Rect::new(6,8,8,10),&rgba());for id in ids{same_source_and_fields(&f.engine,&before,id);}
    let mut f=fixture(16,"png");let before=f.engine.active().unwrap().doc.clone();let mut reads=0;run_with(&mut f.engine,&translated(),|id,meta,object|{reads+=1;let source=checked(id,meta,object)?;std::fs::remove_file(&f.path).unwrap();Ok(source)}).unwrap();assert_eq!(reads,1);assert!(!f.path.exists());pixels(&f.engine,f.id,Rect::new(6,3,8,5),&rgba());same_source_and_fields(&f.engine,&before,f.id);
}

#[test]
fn linked_transform_metadata_first_source_authority_replays_without_changing_preserved_blocks(){
    use photocraft_io::linked::{encode_linked_file,LinkedFile};let mut f=fixture(16,"png");let blue=[0,0,255,255].repeat(4);let mut block=encode_linked_file(&LinkedFile{uuid:f.path.to_string_lossy().into(),file_name:"authority.png".into(),bytes:encoded("png",blue.clone())});block.extend(encode_linked_file(&LinkedFile{uuid:f.path.to_string_lossy().into(),file_name:"ignored.png".into(),bytes:f.bytes.clone()}));f.engine.edit("Linked source metadata",|doc,_|{doc.metadata.psd_global_blocks.push((*b"8BIM",*b"lnk2",Arc::new(block)));Ok(())}).unwrap();std::fs::write(&f.path,b"must not decode disk bytes").unwrap();let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let params=translated();host(&mut f.engine,params.clone()).unwrap();native.execute(COMMAND,params).unwrap();same(&f.engine,&native);same_source_and_fields(&f.engine,&before,f.id);pixels(&f.engine,f.id,Rect::new(6,3,8,5),&blue);
    let mut f=fixture(16,"png");let id=f.id;let block=encode_linked_file(&LinkedFile{uuid:String::new(),file_name:"empty-uuid.png".into(),bytes:encoded("png",blue)});f.engine.edit("Empty UUID cannot supply transform fallback",|doc,_|{doc.metadata.psd_global_blocks.push((*b"8BIM",*b"lnk2",Arc::new(block)));let LayerContent::Smart(object)=&mut doc.layer_mut(id).unwrap().content else{unreachable!()};object.smart_filters.push(SmartFilter{command:"plugin.run".into(),params:json!({"path":"must never run for undecodable source"}),visible:true,opacity:1.,blend:BlendMode::Normal});Ok(())}).unwrap();std::fs::write(&f.path,b"undecodable real linked source with empty-uuid metadata collision").unwrap();let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let mut reads=0;let params=translated();assert_eq!(run_with(&mut f.engine,&params,|id,meta,object|{reads+=1;assert_eq!(object.source,smart(&before,id).source);checked(id,meta,object)}).unwrap(),native.execute(COMMAND,params).unwrap());assert_eq!(reads,1);same(&f.engine,&native);same_source_and_fields(&f.engine,&before,f.id);fallback_pixel(&f.engine,f.id,5,3);
}

#[test]
fn linked_transform_caps_growing_reader_panic_and_decoded_unsupported_stack_refuse_atomically(){
    for failure in ["oversize","growing","panic","unsupported"]{let mut f=fixture(16,"png");if failure=="oversize"{std::fs::OpenOptions::new().write(true).open(&f.path).unwrap().set_len(super::super::super::MAX_INPUT_BYTES+1).unwrap();}if failure=="unsupported"{let id=f.id;f.engine.edit("Unsupported visible stack",|doc,_|{let LayerContent::Smart(object)=&mut doc.layer_mut(id).unwrap().content else{unreachable!()};object.smart_filters.push(SmartFilter{command:"plugin.run".into(),params:json!({"path":"must not execute"}),visible:true,opacity:1.,blend:BlendMode::Normal});Ok(())}).unwrap();}let before=twin(&f.engine);let error=match failure{"oversize"|"unsupported"=>host(&mut f.engine,translated()).unwrap_err(),"panic"=>run_with(&mut f.engine,&translated(),|_,_,_|panic!("injected transform reader panic")).unwrap_err(),_=>{struct Growing{read:usize,max:usize}impl Read for Growing{fn read(&mut self,out:&mut[u8])->std::io::Result<usize>{self.max=self.max.max(out.len());out.fill(0x7a);self.read+=out.len();Ok(out.len())}}let mut reader=Growing{read:0,max:0};let error=run_with(&mut f.engine,&translated(),|_,_,_|super::super::super::smart::replay_read_with_limit(&mut reader,32).map(|bytes|Some(("growing.png".into(),Arc::new(bytes))))).unwrap_err();assert_eq!(reader.read,33);assert!(reader.max<=64*1024);error}};match failure{"panic"=>{assert!(error.contains(COMMAND));assert!(error.contains("internal error"));},"unsupported"=>assert!(error.contains("does not support")),_=>assert!(error.contains("512MB"))}unchanged(&f.engine,&before);}
    let mut f=fixture(16,"png");let group=f.group;let id=f.id;let other=f.other;let late=f.directory.0.join("late-oversize.png");std::fs::File::create(&late).unwrap().set_len(super::super::super::MAX_INPUT_BYTES+1).unwrap();f.engine.edit("Late group source refusal",|doc,active|{let first=doc.remove(id).unwrap();doc.layer_mut(group).unwrap().children_mut().unwrap().insert(0,first);let LayerContent::Smart(object)=&mut doc.layer_mut(other).unwrap().content else{unreachable!()};object.source=SmartSource::Linked{path:late.to_string_lossy().into()};*active=Some(group);Ok(())}).unwrap();let index=f.engine.active_index().unwrap();f.engine.execute("document.activate",json!({"document":index})).unwrap();let before=twin(&f.engine);let mut visits=Vec::new();let mut params=translated();params["layer"]=json!(group.0);let error=run_with(&mut f.engine,&params,|id,meta,object|{visits.push(id);checked(id,meta,object)}).unwrap_err();assert!(error.contains("512MB"));assert_eq!(visits,vec![f.id,f.other]);unchanged(&f.engine,&before);
}

#[test]
fn linked_transform_coalescing_native_context_slices_presets_and_older_fade_remain_intact(){
    use photocraft_engine::preset_store::{open,MemBackend};let mut f=fixture(16,"png");let before=f.engine.active().unwrap().doc.clone();let fade=f.engine.edit_state.fade.clone();let past=f.engine.active().unwrap().history.past_len();let journal=f.engine.journal.len();let mut native=twin(&f.engine);let actual=MemBackend::default();let expected=MemBackend::default();f.engine.attach_preset_store(open(Box::new(actual.clone())));native.attach_preset_store(open(Box::new(expected.clone())));for owner in [&mut f.engine,&mut native]{let mut preset=owner.tools.presets[0].clone();preset.name="Pending transform brush".into();preset.group="Transform owner".into();preset.builtin=false;owner.tools.presets.push(preset);owner.brush_presets_changed();}let files=actual.files.lock().unwrap().clone();let unchanged_before=twin(&f.engine);assert!(run_with(&mut f.engine,&translated(),|_,_,_|Err("injected source refusal".into())).is_err());unchanged(&f.engine,&unchanged_before);assert_eq!(*actual.files.lock().unwrap(),files);for _ in 0..2{let params=json!({"layer":f.id.0,"matrix":[1,0,0,1,1,0],"rect":[2,1,4,3],"coalesce":"smart-transform"});host(&mut f.engine,params.clone()).unwrap();native.execute(COMMAND,params).unwrap();same(&f.engine,&native);assert_eq!(f.engine.edit_state.fade,fade);}assert_ne!(*actual.files.lock().unwrap(),files);assert_eq!(*actual.files.lock().unwrap(),*expected.files.lock().unwrap());assert!(open(Box::new(actual)).presets.iter().any(|preset|preset.name=="Pending transform brush"));assert_eq!(f.engine.active().unwrap().history.past_len(),past+1);assert_eq!(f.engine.active().unwrap().history.undo_label(),Some(LABEL));assert_eq!(f.engine.journal.len(),journal+2);assert_eq!(f.engine.active().unwrap().doc.slices.list[0].rect,Rect::new(5,1,7,3));let after=f.engine.active().unwrap().doc.clone();f.engine.execute("edit.undo",json!({})).unwrap();native.execute("edit.undo",json!({})).unwrap();same(&f.engine,&native);assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before));f.engine.execute("edit.redo",json!({})).unwrap();native.execute("edit.redo",json!({})).unwrap();same(&f.engine,&native);assert_eq!(f.engine.active().unwrap().doc,after);
}

#[test]
fn linked_transform_actual_host_immutable_publish_reopen_undo_redo_retains_source_and_projective_state(){
    let mut f=fixture(16,"psb");f.engine.active_mut().unwrap().channel_view.target=photocraft_engine::channel_cmds::ChannelTarget::Color(1);let before=f.engine.active().unwrap().doc.clone();let labels=f.engine.active().unwrap().history.entries();host(&mut f.engine,json!({"rect":[2,1,4,3],"quad":[[4,2],[8,2],[7,6],[3,5]]})).unwrap();let after=f.engine.active().unwrap().doc.clone();let mut session=super::super::super::PhotoSession{engine:f.engine,color_settings:None,version:String::new(),original_path:None,writer:Default::default()};let photo=ulid::Ulid::new().to_string();super::super::super::publish(&f.directory.0,&photo,&mut session).unwrap();let saved=f.directory.0.join(format!("{}.pcraft",session.version));let bytes=super::super::super::bundle::portable_bytes(&saved,super::super::super::MAX_INPUT_BYTES as usize).unwrap();std::fs::remove_file(&f.path).unwrap();session.engine.execute("edit.undo",json!({})).unwrap();super::super::super::publish(&f.directory.0,&photo,&mut session).unwrap();super::super::super::save_view(&f.directory.0,&session).unwrap();let mut reopened=super::super::super::restore_with_settings(&f.directory.0,&session.version,None,false).unwrap();let state=reopened.engine.active().unwrap();assert_eq!(state.doc,before);assert_eq!(state.history.entries(),labels);assert!(state.history.can_redo());assert_eq!(state.channel_view.target,photocraft_engine::channel_cmds::ChannelTarget::Color(1));reopened.engine.execute("edit.redo",json!({})).unwrap();assert_eq!(reopened.engine.active().unwrap().doc,after);same_source_and_fields(&reopened.engine,&before,f.id);assert!(smart(&reopened.engine.active().unwrap().doc,f.id).perspective.is_some());reopened.engine.execute("edit.undo",json!({})).unwrap();assert_eq!(reopened.engine.active().unwrap().doc,before);assert_eq!(bytes,super::super::super::bundle::portable_bytes(&saved,super::super::super::MAX_INPUT_BYTES as usize).unwrap());
}

#[test]
fn linked_transform_native_parameter_lock_target_and_job_errors_precede_checked_source_reads(){
    for mode in ["matrixLength","matrixScalar","singular","missingTransform","degenerateQuad","invalidLayer","invalidChannel","noMask","locked","noActive","array","null","string"]{let mut f=fixture(8,"png");let mut params=translated();match mode{"matrixLength"=>params["matrix"]=json!([1,0,0,1,2]),"matrixScalar"=>params["matrix"]=json!([1,0,"bad",1,2,3]),"singular"=>params["matrix"]=json!([0,0,0,0,0,0]),"missingTransform"=>params=json!({}),"degenerateQuad"=>params=json!({"quad":[[0,0],[0,0],[0,0],[0,0]]}),"invalidLayer"=>params["layer"]=json!(u64::MAX),"invalidChannel"=>params["target"]=json!({"channel":99}),"noMask"=>{let id=f.id;f.engine.edit("Remove mask",|doc,_|{doc.layer_mut(id).unwrap().mask=None;Ok(())}).unwrap();params["target"]=json!("mask");},"locked"=>{let id=f.id;f.engine.edit("Lock layer",|doc,_|{doc.layer_mut(id).unwrap().locks.all=true;Ok(())}).unwrap();},"noActive"=>f.engine.active_mut().unwrap().active_layer=None,"array"=>params=json!([]),"null"=>params=Value::Null,_=>params=json!("invalid")};std::fs::OpenOptions::new().write(true).open(&f.path).unwrap().set_len(super::super::super::MAX_INPUT_BYTES+1).unwrap();let before=twin(&f.engine);let mut native=twin(&f.engine);assert_eq!(host(&mut f.engine,params.clone()).unwrap_err(),native.execute(COMMAND,params).unwrap_err().to_string());unchanged(&f.engine,&before);}
    let mut empty=Session::new();assert_eq!(host(&mut empty,translated()).unwrap_err(),empty.execute(COMMAND,translated()).unwrap_err().to_string());let mut f=fixture(8,"png");let release=Arc::new(AtomicBool::new(false));let worker=release.clone();struct Release(Arc<AtomicBool>);impl Drop for Release{fn drop(&mut self){self.0.store(true,Ordering::Relaxed);}}let _release=Release(release.clone());let started=f.engine.start_job("smart-transform-test",json!({}),"Retained Smart transform job",true,move|context|{while !worker.load(Ordering::Relaxed){context.check()?;std::thread::yield_now();}Ok(())},|_,_|Ok(Value::Null)).unwrap();let photocraft_engine::jobs::Started::Job(job)=started else{panic!("Expected native job")};let before=twin(&f.engine);std::fs::remove_file(&f.path).unwrap();let error=host(&mut f.engine,translated()).unwrap_err();assert_eq!(error,f.engine.execute(COMMAND,translated()).unwrap_err().to_string());assert!(error.contains("Retained Smart transform job"));unchanged(&f.engine,&before);release.store(true,Ordering::Relaxed);f.engine.wait_job(job).unwrap();
}
